@Test
public void testOutOfMemory_1_oe() throws Exception {
    pool = new SoftReferenceObjectPool<>(new SmallPoolableObjectFactory());

    String obj = pool.borrowObject();
    assertEquals("1", obj);
}

@Test
public void testOutOfMemory_2_oe() throws Exception {
    pool = new SoftReferenceObjectPool<>(new SmallPoolableObjectFactory());

    String obj = pool.borrowObject();
    // removed other assertion
    pool.returnObject(obj);
    obj = null;

    assertEquals(1, pool.getNumIdle());
}

@Test
public void testOutOfMemory1000_2_oe() throws Exception {
    pool = new SoftReferenceObjectPool<>(new SmallPoolableObjectFactory());

    for (int i = 0 ; i < 1000 ; i++) {
        pool.addObject();
    }

    String obj = pool.borrowObject();
    // removed other assertion
    pool.returnObject(obj);
    obj = null;

    assertEquals(1000, pool.getNumIdle());
}

